import React, { forwardRef } from 'react';
import styled from 'styled-components';

import {
  selectedBaseStyles,
  ActionButton,
} from './action-group/ActionButton.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

// #region Typings
export interface NavItemOwnProps
  extends WithChildren,
    StylingProps,
    DataTestId {
  /**
   * The route where the NavItem navigates to.
   */
  href?: string;
  /**
   * Whether the NavItem is disabled.
   * @defaultValue false
   */
  disabled?: boolean;
  /**
   * Whether the NavItem is selected.
   * @defaultValue false
   */
  isSelected?: boolean;
}

export type NavItemProps<E extends React.ElementType> =
  PolymorphicComponentProps<E, NavItemOwnProps>;
// #endregion

// #region StyledComponents
const StyledNavItem = styled(ActionButton)({
  '&:not([role="menuitem"]).active': selectedBaseStyles,
});
// #endregion

/**
 * A navigation item which can be used to go to a specific route.
 */
export const NavItem: <E extends React.ElementType = 'a'>(
  props: NavItemProps<E>,
) => React.ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends React.ElementType>(
    props: NavItemProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      disabled = false,
      isSelected = false,
      as,
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: NavItemProps<E> = props;

    return (
      <StyledNavItem
        ref={forwardedRef}
        data-testid={dataTestId}
        forwardedAs={as ?? 'a'}
        type="button"
        disabled={disabled}
        isSelected={isSelected}
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
      >
        {children}
      </StyledNavItem>
    );
  },
);

(NavItem as typeof NavItem & { displayName: string }).displayName =
  'AppHeader.NavItem';
